// ===== Vitis Mundi atlas links in region lessons =====
// The first mention of each place the atlas knows (region, appellation, château, cru) becomes a link that
// opens it on the globe, and a strip under the lesson title lists the main places. The name index
// (data/atlas-index.js, ~270 KB, generated by tools/build_atlas_index.py) loads only when a region lesson opens.
const ATLAS_URL = "https://vitismundi.app/#";
const UNIT_CC = {
  R1: ["fr"], R2: ["it"], R3: ["es", "pt"],
  R4: ["de", "at", "hu", "gr", "ch", "hr", "si", "ge", "md", "ro", "bg", "lb", "il", "cy", "tr", "mk", "am", "rs", "sk", "cz"],
  R5: ["us", "ca", "ar", "cl", "za", "au", "nz", "uy", "br", "cn", "jp", "in", "mx"]
};
const LESSON_CC = { sp1: ["fr", "es", "it", "gb", "de", "us", "au", "nz", "za"], fo2: ["fr", "pt", "es", "it", "au", "za", "hu", "gr", "cy"] };
const ATLAS_MAX_CHIPS = 8;
let atlasLoad = null;

function atlasScope(l) { return LESSON_CC[l.id] || UNIT_CC[l.unit] || null; }
function loadAtlas() {
  if (typeof ATLAS !== "undefined") return Promise.resolve();
  return atlasLoad || (atlasLoad = new Promise((ok, bad) => {
    const s = document.createElement("script"); s.src = "assets/js/data/atlas-index.js";
    s.onload = ok; s.onerror = () => { atlasLoad = null; bad(); }; document.head.appendChild(s);
  }));
}
const reEsc = t => t.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

function atlasMatcher(ccs) {
  const byName = new Map();
  ccs.forEach(cc => (ATLAS[cc] || []).forEach(([n, id, k]) => { if (!byName.has(n)) byName.set(n, { id, k, n }); }));
  if (!byName.size) return null;
  const names = [...byName.keys()].sort((a, b) => b.length - a.length).map(reEsc);
  return { byName, re: new RegExp(`(?<![\\p{L}\\p{N}'’])(?:${names.join("|")})(?![\\p{L}\\p{N}])`, "gu") };
}

// Wrap the first mention of each place in the lesson prose; returns places in reading order.
function linkPlaces(root, m) {
  const seen = new Map(), walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
    acceptNode: n => n.parentElement.closest("a,h1,h2,h3,th,.atlas-strip") ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT });
  const nodes = []; while (walker.nextNode()) nodes.push(walker.currentNode);
  const first = nodes.find(n => n.nodeValue.trim());  // the opening word carries the drop cap: leave it whole
  nodes.forEach(node => {
    const txt = node.nodeValue; let last = 0, frag = null; m.re.lastIndex = 0; let hit;
    while ((hit = m.re.exec(txt))) {
      const p = m.byName.get(hit[0]); if (!p || seen.has(p.id)) continue;
      if (node === first && !txt.slice(0, hit.index).trim()) continue;
      seen.set(p.id, p); frag = frag || document.createDocumentFragment();
      frag.append(txt.slice(last, hit.index));
      const a = document.createElement("a"); a.className = "atlas-ref"; a.href = ATLAS_URL + p.id; a.target = "_blank"; a.rel = "noopener";
      a.title = `Open ${p.n} on the Vitis Mundi atlas`; a.textContent = hit[0]; frag.append(a); last = hit.index + hit[0].length;
    }
    if (frag) { frag.append(txt.slice(last)); node.replaceWith(frag); }
  });
  return [...seen.values()];
}

function atlasStrip(places, ccs, title) {
  const rank = { c: 0, r: 1, a: 2, s: 3 };
  const pick = places.filter(p => p.k !== "s").sort((a, b) => rank[a.k] - rank[b.k]).slice(0, ATLAS_MAX_CHIPS);
  if (!pick.length) return "";
  const home = ccs.length === 1 ? ccs[0] : null;
  return `<div class="eyebrow">On the atlas</div><div class="atlas-chips">${pick.map(p => `<a class="chip" href="${ATLAS_URL}${p.id}" target="_blank" rel="noopener">${esc(p.n)}</a>`).join("")}${home ? `<a class="chip more" href="${ATLAS_URL}${home}" target="_blank" rel="noopener">The whole country ↗</a>` : ""}</div>`;
}

function annotateLesson(id) {
  const l = LBY[id], ccs = l && atlasScope(l), prose = document.querySelector(".read .prose"), strip = document.getElementById("atlasstrip");
  if (!ccs || !prose) return;
  loadAtlas().then(() => {
    if (location.hash !== "#lesson-" + id || prose.dataset.atlas) return;  // the reader has moved on, or already done
    prose.dataset.atlas = "1";
    const m = atlasMatcher(ccs); if (!m) return;
    const places = linkPlaces(prose, m);
    if (strip) { strip.innerHTML = atlasStrip(places, ccs, l.title); strip.hidden = !strip.innerHTML; }
  }).catch(() => { /* offline or blocked: the lesson reads fine without links */ });
}

// ===== Region maps in lessons =====
// Each map is a small generated file (tools/build_lesson_maps.py) loaded only when its lesson opens.
// Numbers on the map match the list beneath it; each name opens that region on the atlas.
const mapLoads = {};
function loadMap(key) {
  if (MAPDATA[key]) return Promise.resolve();
  return mapLoads[key] || (mapLoads[key] = new Promise((ok, bad) => {
    const s = document.createElement("script"); s.src = "assets/js/data/maps/" + key + ".js";
    s.onload = ok; s.onerror = () => { delete mapLoads[key]; bad(); }; document.head.appendChild(s);
  }));
}
function showLessonMaps(id) {
  const keys = LESSON_MAPS[id], box = document.getElementById("lmaps");
  if (!keys || !box) return;
  Promise.all(keys.map(loadMap)).then(() => {
    if (location.hash !== "#lesson-" + id) return;
    box.innerHTML = keys.map(k => { const m = MAPDATA[k];
      return `<figure class="lmap">${m.svg}<figcaption><span class="eyebrow">${esc(m.t)}</span><ol>${m.legend.map(([n, rid]) =>
        `<li><a href="${ATLAS_URL}${rid}" target="_blank" rel="noopener">${esc(n)}</a></li>`).join("")}</ol></figcaption></figure>`; }).join("");
    box.hidden = false;
  }).catch(() => { /* offline or blocked: the lesson reads fine without a map */ });
}
